import hashlib
import hmac
import os
import unicodedata
from urllib.parse import urlparse, urljoin
from flask import Flask, request, redirect, abort, session
import secrets

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET')
if not WEBHOOK_SECRET:
    raise RuntimeError(
        'WEBHOOK_SECRET environment variable must be set to a strong, secret value. '
        'Refusing to start with a missing or default webhook secret.'
    )

TRUSTED_DOMAINS = [
    'app.internal.corp',
    'dashboard.internal.corp',
    'auth.internal.corp',
    'cdn.internal.corp',
]

ALLOWED_SCHEMES = ('https',)

def verify_webhook_signature(payload: bytes, signature: str) -> bool:
    """Verify HMAC-SHA256 webhook signature."""
    expected = hmac.new(
        WEBHOOK_SECRET.encode('utf-8'),
        payload,
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)


def normalize_host(host: str) -> str:
    """Normalize hostname for consistent comparison.
    Applies NFKC normalization, strips trailing dots, and lowercases."""
    if not host:
        return ''
    # Strip port if present
    if ':' in host:
        host = host.rsplit(':', 1)[0]
    # Strip trailing dot (FQDN notation)
    host = host.rstrip('.')
    # Apply Unicode NFKC normalization FIRST for IDN handling
    host = unicodedata.normalize('NFKC', host)
    # Lowercase AFTER normalization
    host = host.lower()
    return host


def is_trusted_domain(host: str) -> bool:
    """Check if the host matches a trusted domain exactly."""
    normalized = normalize_host(host)
    for domain in TRUSTED_DOMAINS:
        if normalized == domain:
            return True
        # Allow subdomains of trusted domains
        if normalized.endswith('.' + domain):
            return True
    return False


def validate_redirect_url(url: str) -> bool:
    """Validate that a redirect URL is safe.

    Security checks:
    1. Must use HTTPS scheme
    2. Must have a valid host
    3. Host must be in trusted domains list
    4. No userinfo in URL
    5. No embedded credentials
    """
    if not url or not isinstance(url, str):
        return False

    # Reject protocol-relative URLs
    if url.startswith('//'):
        return False

    # Parse the URL
    parsed = urlparse(url)

    # Check scheme
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False

    # Reject URLs with userinfo (potential confusion)
    if parsed.username or parsed.password:
        return False

    # Must have a hostname
    if not parsed.hostname:
        return False

    # Normalize the hostname before validation
    normalized_host = normalize_host(parsed.hostname)

    # Ensure only ASCII after normalization (reject non-ASCII IDN attempts)
    if not normalized_host.isascii():
        return False

    # Validate against trusted domains
    if not is_trusted_domain(normalized_host):
        return False

    return True


def sanitize_redirect_target(url: str) -> str:
    """Sanitize and normalize the redirect target URL.
    Applied after validation to ensure consistent URL format."""
    parsed = urlparse(url)
    # Normalize the host component
    host = normalize_host(parsed.hostname) if parsed.hostname else ''
    # Reconstruct with normalized host
    port_str = f':{parsed.port}' if parsed.port and parsed.port != 443 else ''
    path = parsed.path or '/'
    query = f'?{parsed.query}' if parsed.query else ''
    fragment = f'#{parsed.fragment}' if parsed.fragment else ''
    return f'{parsed.scheme}://{host}{port_str}{path}{query}{fragment}'


@app.route('/auth/callback')
def auth_callback():
    """OAuth callback handler that redirects to the original destination."""
    next_url = request.args.get('next', request.args.get('redirect_uri', ''))

    if not next_url:
        return redirect('https://dashboard.internal.corp/')

    # Validate the redirect target
    if not validate_redirect_url(next_url):
        abort(400, description='Invalid redirect target')

    # Sanitize for consistent format
    safe_url = sanitize_redirect_target(next_url)
    return redirect(safe_url)


@app.route('/webhook/deploy', methods=['POST'])
def deploy_webhook():
    """Handle deployment webhook with redirect to status page."""
    sig = request.headers.get('X-Hub-Signature-256', '')
    if not verify_webhook_signature(request.get_data(), sig):
        abort(403)

    callback_url = request.json.get('callback_url', '') if request.json else ''

    if callback_url:
        if not validate_redirect_url(callback_url):
            abort(400, description='Invalid callback URL')
        safe_url = sanitize_redirect_target(callback_url)
        return redirect(safe_url, code=302)

    return {'status': 'accepted'}, 202


@app.route('/sso/redirect')
def sso_redirect():
    """SSO redirect endpoint for federated authentication."""
    target = request.args.get('target', '')

    if not target:
        return redirect('https://auth.internal.corp/login')

    # Handle relative paths
    if target.startswith('/') and not target.startswith('//'):
        return redirect(f'https://app.internal.corp{target}')

    # Validate absolute URLs
    if not validate_redirect_url(target):
        abort(400, description='Untrusted redirect target')

    safe_url = sanitize_redirect_target(target)
    return redirect(safe_url)


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8443, ssl_context='adhoc')
